const $=s=>document.querySelector(s);
const frames=[
 {name:'Wayfinder',icon:'🦊',cost:1,atk:2,hp:2,desc:'Quick and adaptable'}, {name:'Ironbark',icon:'🛡️',cost:2,atk:2,hp:4,desc:'Stands firm in a lane'}, {name:'Cloudlancer',icon:'🦅',cost:2,atk:3,hp:3,desc:'A precise striker'}, {name:'Stonehorn',icon:'🐂',cost:3,atk:4,hp:5,desc:'A towering bruiser'}, {name:'Mothkeeper',icon:'🦋',cost:1,atk:1,hp:3,desc:'A patient support'}
];
const sigils=[
 {name:'Stormbound',desc:'Keen · +1 attack',atk:1,trait:'Keen'}, {name:'Thornmarked',desc:'Thorns · +1 health',hp:1,trait:'Thorns'}, {name:'Dawnlit',desc:'Mend · heal 2 on strike',trait:'Mend'}, {name:'Emberveined',desc:'Venom · +1 damage to Regent',trait:'Venom'}, {name:'Quickened',desc:'Rush · strikes this turn',trait:'Rush'}, {name:'Moonward',desc:'Ward · shield absorbs 1 hit',trait:'Ward'}
];
const cores=[
 {name:'Battle Hymn',desc:'Rally · +1 attack on summon',trait:'Rally'}, {name:'Heartstone',desc:'Vital · +1 health',hp:1,trait:'Vital'}, {name:'Sunflare',desc:'Searing · +1 damage to foes',trait:'Searing'}, {name:'Leechroot',desc:'Leech · heal 1 on strike',trait:'Leech'}, {name:'Windsong',desc:'Fleet · +1 attack, +1 health',atk:1,hp:1,trait:'Fleet'}, {name:'Soulglass',desc:'Piercing · excess power hits Regent',trait:'Piercing'}
];
const mutations=[
 {name:'Wild Bloom',desc:'+1 health · Verdant',hp:1,trait:'Verdant'}, {name:'Volcanic',desc:'+1 attack · Scorch',atk:1,trait:'Scorch'}, {name:'Twin Soul',desc:'Mend 1 on strike · Bonded',trait:'Bonded'}, {name:'Iron Thread',desc:'+1 health · Ward',hp:1,trait:'Ward'}, {name:'Starfall',desc:'+1 attack · Venom',atk:1,trait:'Venom'}, {name:'Quicksilver',desc:'Rush · +1 attack',atk:1,trait:'Rush'}
];
const catalysts=[
 {name:'Prismatic',desc:'+1 / +1 · Radiant',atk:1,hp:1,trait:'Radiant'}, {name:'Deep Root',desc:'+2 health · Vital',hp:2,trait:'Vital'}, {name:'Ashen Oath',desc:'+2 attack · Scorch',atk:2,trait:'Scorch'}, {name:'Echoing',desc:'Rally · +1 attack on summon',trait:'Rally'}, {name:'Eclipse',desc:'Venom · Mend 1 on strike',trait:'Eclipse'}, {name:'Aegis Core',desc:'Ward · +1 health',hp:1,trait:'Ward'}
];
const foes=[
 {name:'Cinder Scout',icon:'🗡️',atk:1,hp:2}, {name:'Ash Hound',icon:'🐺',atk:2,hp:3}, {name:'Regent Guard',icon:'🪓',atk:2,hp:4}, {name:'Blight Crow',icon:'🐦‍⬛',atk:3,hp:3}, {name:'Iron Reaver',icon:'👹',atk:3,hp:5}, {name:'Dread Colossus',icon:'🗿',atk:4,hp:6}, {name:'Flame Wraith',icon:'👻',atk:4,hp:4}
];
const laneNames=['North pass','Old bridge','Ashen gate'];
let game;
function freshGame(){game={round:1,playerHp:30,enemyHp:35,mana:2,maxMana:2,hand:[],units:[null,null,null],foes:[null,null,null],crafted:false,offers:{},selected:{},picked:null,done:false,log:[],foeCounter:0};game.foes[1]=makeFoe(0);log('A Cinder Scout blocks the Old bridge. The siege begins.');makeOffers();render();}
function pick(arr,n=3){let pool=[...arr],out=[];while(out.length<n&&pool.length){let i=Math.floor(Math.random()*pool.length);out.push(pool.splice(i,1)[0]);}return out}
function makeFoe(index){let tier=Math.min(foes.length-1,Math.floor(index*.9));let f=foes[tier];return {...f,maxHp:f.hp,hp:f.hp,serial:index}}
function makeOffers(){let r=game.round;game.offers={frame:pick(frames.filter(x=>r>=4||x.cost<=2)),sigil:pick(sigils),core:pick(cores)};if(r>=3)game.offers.mutation=pick(mutations);if(r>=5)game.offers.catalyst=pick(catalysts);game.selected={};}
function log(text){game.log.unshift({round:game.round,text});game.log=game.log.slice(0,7)}
function escape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderChoices(){for(const key of ['frame','sigil','core','mutation','catalyst']){let host=$(`#${key}Choices`);if(!host)continue;let choices=game.offers[key];if(!choices){host.parentElement.remove();continue}host.innerHTML=choices.map((o,i)=>`<button class="choice ${game.selected[key]===i?'selected':''}" data-part="${key}" data-index="${i}"><strong>${escape(o.name)}</strong><span>${escape(o.desc)}</span></button>`).join('')}
// Add the advanced recipe rows when the forge evolves.
const grid=$('.recipe-grid');grid.querySelectorAll('.advanced-row').forEach(x=>x.remove());[['mutation','MUTATION','new trait'],['catalyst','CATALYST','final imprint']].forEach(([key,label,sub])=>{if(!game.offers[key])return;let row=document.createElement('div');row.className='recipe-row advanced-row';row.innerHTML=`<div class="recipe-label"><span class="recipe-symbol ${key==='catalyst'?'core-symbol':'sigil-symbol'}">${key==='catalyst'?'✷':'✹'}</span><span><b>${label}</b><small>${sub}</small></span></div><div class="choices" id="${key}Choices"></div>`;grid.append(row);row.querySelector('.choices').innerHTML=game.offers[key].map((o,i)=>`<button class="choice ${game.selected[key]===i?'selected':''}" data-part="${key}" data-index="${i}"><strong>${escape(o.name)}</strong><span>${escape(o.desc)}</span></button>`).join('')})}
function recipe(){let required=Object.keys(game.offers);if(required.some(k=>game.selected[k]===undefined))return null;let parts=required.map(k=>game.offers[k][game.selected[k]]),frame=parts[0],stats=parts.reduce((a,p)=>({atk:a.atk+(p.atk||0),hp:a.hp+(p.hp||0)}),{atk:frame.atk,hp:frame.hp});let traits=parts.slice(1).map(p=>p.trait).filter(Boolean);if(game.round>=3){stats.atk+=1;stats.hp+=1}return {name:`${parts[1].name} ${frame.name}`,icon:frame.icon,cost:frame.cost,atk:stats.atk,hp:stats.hp,maxHp:stats.hp,traits:[...new Set(traits)],parts:parts.map(p=>p.name),ready:traits.includes('Rush'),shield:traits.includes('Ward'),round:game.round}}
function renderPreview(){let c=recipe(),p=$('#recipePreview');if(!c){p.innerHTML='<span class="preview-icon">✦</span><span>Choose one piece from each row to reveal your champion.</span>';$('#forgeBtn').disabled=true;return}p.innerHTML=`<span class="preview-icon">${c.icon}</span><span><b>${escape(c.name)}</b> · <b>${c.cost} mana</b> · <b>${c.atk}⚔ ${c.hp}♥</b> · ${escape(c.traits.join(' / ')||'No trait')}</span>`;$('#forgeBtn').disabled=game.crafted||game.done}
function unitMarkup(u,foe=false){if(!u)return `<div class="empty-slot">${foe?'Awaiting threat':'Deploy champion'}</div>`;return `<div class="lane-unit ${foe?'foe':''}"><span class="unit-emoji">${u.icon}</span><div class="unit-info"><div class="unit-name">${escape(u.name)}</div><div class="unit-keyword">${foe?'REGENT':'YOU'}${u.traits?.length?' · '+escape(u.traits.slice(0,2).join(' · ')):''}${u.ready===false?' · resting':''}</div></div><div class="unit-stats"><span>${u.atk}⚔</span><span>${u.hp}♥</span></div></div>`}
function render(){if(!game)return;$('#playerHp').textContent=game.playerHp;$('#enemyHp').textContent=game.enemyHp;$('#playerBar').style.width=Math.max(0,game.playerHp/30*100)+'%';$('#enemyBar').style.width=Math.max(0,game.enemyHp/35*100)+'%';$('#round').textContent=game.round;$('#mana').textContent=game.mana;$('#manaMax').textContent=game.maxMana;$('#battlefield').innerHTML=laneNames.map((name,i)=>`<div class="lane" data-lane="${i}"><span class="lane-label">${name}</span><div class="enemy-lane">${unitMarkup(game.foes[i],true)}</div><div class="player-lane">${unitMarkup(game.units[i])}</div></div>`).join('');renderChoices();renderPreview();renderHand();renderSidebar();$('#endTurnBtn').disabled=!game.crafted||game.done;$('#turnHint').textContent=game.picked!==null?'Choose a lane to deploy your champion.':game.crafted?'Deploy a champion or end your turn.':'Forge a card, then deploy your champion.';$('#forgeNote').textContent=game.crafted?'Champion forged · ready for battle':game.round>=5?'Five-part recipes · choose every piece':game.round>=3?'Recipe evolved · a mutation joins the forge':'Choose one piece from each row';$('#forgePanel').classList.toggle('forged',game.crafted);$('#handCount').textContent=game.hand.length}

