$('#handCount').textContent=game.hand.length}
function renderHand(){let host=$('#hand');if(!game.hand.length){host.innerHTML='<div class="empty-hand">Your hand is waiting for its first creation.</div>';return}host.innerHTML=game.hand.map((c,i)=>`<article class="hand-card ${c.cost>game.mana?'unplayable':''} ${game.picked===i?'selected':''}" data-card="${i}" tabindex="0" role="button" aria-label="Select ${escape(c.name)}, costs ${c.cost} mana"><div class="hand-card-top"><span class="card-cost">${c.cost}</span><span class="card-icon">${c.icon}</span></div><h3>${escape(c.name)}</h3><p>${escape(c.traits.join(' · ')||'A capable champion')}</p><div class="card-bottom"><span><b>${c.atk}</b> ATK</span><span><i>${c.hp}</i> HP</span></div></article>`).join('')}
function renderSidebar(){let art,title,text,rule;if(game.done){art=game.enemyHp<=0?'☀':'⚔';title=game.enemyHp<=0?'The Regent is broken':'The wilds are yours';text=game.enemyHp<=0?'Your crafted champions shattered the Ashen Regent’s siege. A new legend begins.':'You held the line through seven rounds. The Ashen Regent retreats into the wilds.';rule='Run complete · restart to forge again.'}else if(game.round>=5){art='👑';title='The Regent approaches';text='The Ashen Regent is preparing to enter the battlefield. Your recipes now carry two extra imprints.';rule='The final rounds are here. Protect your vitality.'}else if(game.round>=3){art='🧬';title='Wild magic awakens';text='The forge has evolved. Every new champion can take a mutation alongside its core and sigil.';rule='Your recipes now have four parts.'}else{art=game.round===1?'☠':'🪓';title=game.round===1?'A scout blocks the pass':'The siege advances';text=game.round===1?'The regent is testing your defenses. Build a champion and make your opening move.':'Fresh enemies are closing in. Choose a lane and keep your vitality above zero.';rule='Champions strike first. Unanswered enemies hit your vitality.'}$('#intentArt').textContent=art;$('#intentTitle').textContent=title;$('#intentText').textContent=text;$('#intentRule').textContent=rule;$('#log').innerHTML=game.log.map((e,i)=>`<div class="log-entry ${i===0?'latest':''}"><span class="log-round">R${e.round}</span><span>${e.text}</span></div>`).join('')}
function playCard(index,lane){let c=game.hand[index];if(!c||game.done)return;if(c.cost>game.mana){log('Not enough mana to deploy '+c.name+'.');game.picked=null;render();return}let replaced=game.units[lane];game.mana-=c.cost;game.units[lane]={...c,hp:c.maxHp,ready:c.traits.includes('Rush'),shield:c.traits.includes('Ward')};if(c.traits.includes('Rally'))game.units[lane].atk+=1;if(c.traits.includes('Vital'))game.units[lane].hp++,game.units[lane].maxHp++;if(c.traits.includes('Fleet'))game.units[lane].atk++,game.units[lane].hp++,game.units[lane].maxHp++;if(c.traits.includes('Ward'))game.units[lane].hp++,game.units[lane].maxHp++;if(c.traits.includes('Radiant'))game.units[lane].atk++,game.units[lane].hp++,game.units[lane].maxHp++;if(c.traits.includes('Scorch'))game.units[lane].atk++;if(c.traits.includes('Verdant'))game.units[lane].hp++,game.units[lane].maxHp++;game.hand.splice(index,1);game.picked=null;log(`${c.name} deployed to ${laneNames[lane]}${replaced?' (replacing '+replaced.name+')':''}.`);render()}
function choosePart(key,index){if(game.crafted||game.done)return;game.selected[key]=index;renderChoices();renderPreview()}
function forge(){if(game.done||game.crafted)return;let c=recipe();if(!c)return;game.hand.push(c);game.crafted=true;log(`Forged ${c.name}: ${c.atk} attack, ${c.hp} health${c.traits.length?' · '+c.traits.join(', '):''}.`);render()}
function attackTurn(){// Champions attack in lane order; surviving foes retaliate.
for(let i=0;i<3;i++){let p=game.units[i],e=game.foes[i];if(p&&p.ready!==false){let hit=p.atk+(p.traits.includes('Searing')?1:0)+(p.traits.includes('Scorch')?1:0);if(e){let before=e.hp;e.hp-=hit;if(p.traits.includes('Venom')||p.traits.includes('Eclipse'))e.hp-=1;if(p.traits.includes('Mend'))game.playerHp=Math.min(30,game.playerHp+2);if(p.traits.includes('Leech')||p.traits.includes('Bonded')||p.traits.includes('Eclipse'))game.playerHp=Math.min(30,game.playerHp+1);if(e.hp<=0){let spill=0;if(p.traits.includes('Piercing'))spill=Math.max(0,hit-before);game.foes[i]=null;game.enemyHp-=spill;log(`${p.name} defeats ${e.name}${spill?' and pierces for '+spill+'!':'!'}`)}else{e.hp=Math.max(0,e.hp);log(`${p.name} strikes ${e.name} for ${hit}${(p.traits.includes('Venom')||p.traits.includes('Eclipse'))?' + venom':''}.`)}}else{let damage=hit+(p.traits.includes('Venom')||p.traits.includes('Eclipse')?1:0);game.enemyHp-=damage;if(p.traits.includes('Mend'))game.playerHp=Math.min(30,game.playerHp+2);if(p.traits.includes('Leech')||p.traits.includes('Bonded')||p.traits.includes('Eclipse'))game.playerHp=Math.min(30,game.playerHp+1);log(`${p.name} hits the Regent for ${damage}${p.traits.includes('Mend')||p.traits.includes('Leech')?' and restores vitality':''}.`)} }
if(game.enemyHp<=0)break}
if(game.enemyHp>0){for(let i=0;i<3;i++){let e=game.foes[i];if(!e)continue;let p=game.units[i];if(p){let damage=e.atk;if(p.shield){p.shield=false;damage=Math.max(0,damage-1);log(`${p.name}'s Ward absorbs a blow.`)}p.hp-=damage;log(`${e.name} hits ${p.name} for ${damage}.`);if(p.hp<=0){game.units[i]=null;log(`${p.name} falls in the ${laneNames[i]}.`)}}else{game.playerHp-=e.atk;log(`${e.name} strikes your vitality for ${e.atk}.`)}}}
if(game.playerHp<=0){game.playerHp=0;finish(false);return}if(game.enemyHp<=0){game.enemyHp=0;finish(true);return}if(game.round>=7){finish(true);return}nextRound()}
function nextRound(){game.round++;game.maxMana=Math.min(6,game.maxMana+1);game.mana=game.maxMana;game.crafted=false;game.picked=null;let open=[0,1,2].filter(i=>!game.foes[i]);if(open.length){let lane=open[Math.floor(Math.random()*open.length)],f=makeFoe(game.foeCounter++);game.foes[lane]=f;log(`${f.name} enters at ${laneNames[lane]} (${f.atk} attack / ${f.hp} health).`)}else{let lane=Math.floor(Math.random()*3),f=game.foes[lane];f.atk++;f.hp++;f.maxHp++;log(`The Regent's forces swell at ${laneNames[lane]}: ${f.name} gains +1/+1.`)}makeOffers();render()}
function finish(win){game.done=true;game.crafted=true;game.picked=null;render();let modal=$('#modal');$('#modalEyebrow').textContent=win?'SIEGE BROKEN':'THE FORGE FALLS';$('#modalTitle').textContent=win?'A legend is forged':'The wilds fall silent';$('#modalBody').innerHTML=`<div class="result-icon">${win?'🏆':'🕯️'}</div><p>${win?`You ${game.enemyHp<=0?'defeated the Ashen Regent':'survived all seven rounds'} with <b>${game.playerHp} vitality</b> remaining.`:`The Ashen Regent overcame you in round ${game.round}. Every legend starts with another attempt.`}</p><p>Champions forged: <b>${game.log.filter(x=>x.text.startsWith('Forged ')).length}</b></p>`;$('#modalAction').textContent='Forge another run';$('#modal').classList.remove('hidden')}

