const modal=$('#modal');
function showRules(){ $('#modalEyebrow').textContent='A FIELD GUIDE';$('#modalTitle').textContent='How to play';$('#modalBody').innerHTML='<ul><li><b>Forge one champion each turn.</b> Choose a frame, sigil, and core. Your recipes gain extra ingredients as the siege advances.</li><li><b>Spend mana to deploy.</b> Click a card in your hand, then choose one of the three lanes. Playing into your own occupied lane replaces that champion.</li><li><b>End your turn.</b> Ready champions attack first. Foes then strike their lane, or damage your vitality if the lane is open.</li><li><b>Win the siege.</b> Defeat the Regent or survive all seven rounds. Keep your vitality above zero.</li><li><b>Traits matter.</b> Rush attacks immediately, Ward absorbs one hit, Mend heals on strike, and Venom adds damage to the Regent.</li></ul>';$('#modalAction').textContent='Got it';modal.classList.remove('hidden')}
$('#rulesBtn').addEventListener('click',showRules);
$('#modalClose').addEventListener('click',()=>modal.classList.add('hidden'));
$('#modalAction').addEventListener('click',()=>{if(game.done)freshGame();modal.classList.add('hidden')});
$('#restartBtn').addEventListener('click',()=>{modal.classList.add('hidden');freshGame()});
$('#forgeBtn').addEventListener('click',forge);
$('#endTurnBtn').addEventListener('click',()=>{if(game.crafted&&!game.done)attackTurn()});
document.addEventListener('click',e=>{let part=e.target.closest('[data-part]');if(part){choosePart(part.dataset.part,Number(part.dataset.index));return}let card=e.target.closest('[data-card]');if(card){let i=Number(card.dataset.card);if(game.hand[i]?.cost>game.mana){log('That champion costs more mana than you have.');render();return}game.picked=game.picked===i?null:i;render();return}let lane=e.target.closest('[data-lane]');if(lane&&game.picked!==null)playCard(game.picked,Number(lane.dataset.lane))});
document.addEventListener('keydown',e=>{if(e.key==='Escape')modal.classList.add('hidden');if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-card]')){e.preventDefault();e.target.click()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-lane]')){e.preventDefault();e.target.click()}});
freshGame();

